-- V484__seed_jee_mains_question_bank_and_full_mocks_1_35.sql
-- Removes old 2-question JEE placeholder (a2222222-...0022),
-- seeds 150 distinct curated NTA-Rationalized JEE Main Question Bank items
-- (Physics 50, Chemistry 50, Maths 50: 35 MCQ + 15 NUMERICAL per subject),
-- and generates Full-Length JEE Main NTA CBT Mock Series Set 1..35
-- (75 Compulsory Questions / 300 Marks / 180 Mins, +4 / -1 on both Sec A & Sec B).

DO $$
DECLARE
    v_jee_id UUID;
    i INT;
    q_idx INT;
    v_test_id UUID;
    v_phy_mcqs UUID[];
    v_phy_nums UUID[];
    v_chem_mcqs UUID[];
    v_chem_nums UUID[];
    v_math_mcqs UUID[];
    v_math_nums UUID[];
    q_id UUID;
BEGIN
    SELECT id INTO v_jee_id FROM learn_exam_types WHERE slug = 'jee-mains' LIMIT 1;
    IF v_jee_id IS NULL THEN
        RAISE EXCEPTION 'jee-mains exam_type missing';
    END IF;

    -- Remove legacy placeholder test
    DELETE FROM learn_test_attempts WHERE mock_test_id = 'a2222222-0000-0000-0000-000000000022';
    DELETE FROM learn_test_questions WHERE mock_test_id = 'a2222222-0000-0000-0000-000000000022';
    DELETE FROM learn_mock_tests WHERE id = 'a2222222-0000-0000-0000-000000000022';

    -- Clean idempotent reload for JEE Mains question bank & mocks
    DELETE FROM learn_test_questions WHERE mock_test_id::text LIKE '2010%';
    DELETE FROM learn_mock_tests WHERE id::text LIKE '2010%';
    DELETE FROM learn_questions WHERE id::text LIKE '2010%';

    -- ───────────────────────────────────────────────────────────────────────────
    -- 1. PHYSICS QUESTION BANK (35 MCQ + 15 NUMERICAL = 50 Questions)
    -- Linked across Physics topics 65d29b56-1011-2001..2015
    -- ───────────────────────────────────────────────────────────────────────────
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified) VALUES
    ('20100101-0000-4000-8000-000000000001', '65d29b56-1011-2001-0000-000000000001', 'The dimensions of (1/2) ε₀ E² (where ε₀ is permittivity of free space and E is electric field) match those of:', '{"A":"Energy density [M L⁻¹ T⁻²]","B":"Force [M L T⁻²]","C":"Electric flux [M L³ T⁻³ A⁻¹]","D":"Angular momentum [M L² T⁻¹]"}'::jsonb, 'A', 'MCQ', 'Physics', 'Units & Experimental Skills', 4, 1.00, 'NTA_SYNCED', 'Electrostatic energy per unit volume has units J/m³ = [ML⁻¹T⁻²].', 'EASY', 'JEE Main 2024', true),
    ('20100101-0000-4000-8000-000000000002', '65d29b56-1011-2001-0000-000000000002', '10 Vernier scale divisions coincide with 9 main scale divisions (1 MSD = 1 mm). Zero of Vernier lies between 2.4 cm and 2.5 cm with 6th VSD coinciding. If zero error is +0.02 cm, true reading is:', '{"A":"2.44 cm","B":"2.48 cm","C":"2.46 cm","D":"2.42 cm"}'::jsonb, 'A', 'MCQ', 'Physics', 'Units & Experimental Skills', 4, 1.00, 'NTA_SYNCED', 'LC = 0.01 cm => Observed = 2.4 + 0.06 = 2.46 cm. True = 2.46 - (+0.02) = 2.44 cm.', 'MEDIUM', 'JEE Main 2025', true),
    ('20100101-0000-4000-8000-000000000003', '65d29b56-1011-2002-0000-000000000001', 'Position of a particle varies as x = 3t² - t³ (in SI units). At what time does its velocity become maximum?', '{"A":"t = 1 s","B":"t = 2 s","C":"t = 0.5 s","D":"t = 3 s"}'::jsonb, 'A', 'MCQ', 'Physics', 'Kinematics', 4, 1.00, 'NTA_SYNCED', 'v = 6t - 3t²; dv/dt = a = 6 - 6t = 0 at t = 1 s (with d²v/dt² < 0).', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000004', '65d29b56-1011-2002-0000-000000000002', 'A projectile fired at angle 30° achieves horizontal range R₁, and at 60° with same speed achieves R₂. Then R₁ / R₂ equals:', '{"A":"1 : 1","B":"1 : √3","C":"√3 : 1","D":"1 : 3"}'::jsonb, 'A', 'MCQ', 'Physics', 'Kinematics', 4, 1.00, 'NTA_SYNCED', 'Complementary angles θ and (90°-θ) give identical horizontal range u²sin(2θ)/g.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000005', '65d29b56-1011-2002-0000-000000000003', 'A river of width 200 m flows at 3 m/s. A swimmer capable of 5 m/s in still water crosses along the shortest possible path. The time taken is:', '{"A":"50 s","B":"40 s","C":"66.7 s","D":"100 s"}'::jsonb, 'A', 'MCQ', 'Physics', 'Kinematics', 4, 1.00, 'NTA_SYNCED', 'Perpendicular drift-free resultant speed = √(5² - 3²) = 4 m/s => t = 200 / 4 = 50 s.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000006', '65d29b56-1011-2003-0000-000000000001', 'Two masses 4 kg and 6 kg hang via an ideal string over a smooth fixed pulley (g = 10 m/s²). Tension in the string is:', '{"A":"48 N","B":"50 N","C":"24 N","D":"60 N"}'::jsonb, 'A', 'MCQ', 'Physics', 'Laws of Motion', 4, 1.00, 'NTA_SYNCED', 'T = 2m₁m₂g/(m₁+m₂) = 2×4×6×10 / 10 = 48 N.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000007', '65d29b56-1011-2003-0000-000000000002', 'A 5 kg block rests on a horizontal floor with μ_s = 0.4, μ_k = 0.3 (g = 10 m/s²). If a horizontal force of 15 N is applied, friction force acting is:', '{"A":"15 N","B":"20 N","C":"12 N","D":"0 N"}'::jsonb, 'A', 'MCQ', 'Physics', 'Laws of Motion', 4, 1.00, 'NTA_SYNCED', 'f_max = μ_s N = 0.4×50 = 20 N. Since F_ext = 15 N < 20 N, block remains at rest with static friction = 15 N.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000008', '65d29b56-1011-2003-0000-000000000003', 'Maximum safe speed for a car negotiating a smooth banked curve of radius 40 m banked at tanθ = 0.4 (g = 10 m/s²) is:', '{"A":"4√10 m/s","B":"20 m/s","C":"10 m/s","D":"4 m/s"}'::jsonb, 'A', 'MCQ', 'Physics', 'Laws of Motion', 4, 1.00, 'NTA_SYNCED', 'v = √(Rg tanθ) = √(40 × 10 × 0.4) = √160 = 4√10 m/s.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000009', '65d29b56-1011-2004-0000-000000000001', 'Work done by a variable force F = (3x² + 2) î N displacing a particle from x = 0 to x = 2 m is:', '{"A":"12 J","B":"8 J","C":"14 J","D":"10 J"}'::jsonb, 'A', 'MCQ', 'Physics', 'Work Energy Power', 4, 1.00, 'NTA_SYNCED', 'W = ∫₀² (3x² + 2) dx = [x³ + 2x]₀² = 8 + 4 = 12 J.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000010', '65d29b56-1011-2004-0000-000000000002', 'Minimum speed at the lowest point for a stone tied to a string of length L to complete a vertical circle is:', '{"A":"√(5gL)","B":"√(4gL)","C":"√(2gL)","D":"√(gL)"}'::jsonb, 'A', 'MCQ', 'Physics', 'Work Energy Power', 4, 1.00, 'NTA_SYNCED', 'At top T=0 gives v_top = √(gL); energy conservation gives v_bottom = √(5gL).', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000011', '65d29b56-1011-2004-0000-000000000003', 'A ball dropped from height h rebounds from a floor with restitution coefficient e. Height reached after the 2nd bounce is:', '{"A":"e⁴ h","B":"e² h","C":"e h","D":"e³ h"}'::jsonb, 'A', 'MCQ', 'Physics', 'Work Energy Power', 4, 1.00, 'NTA_SYNCED', 'Height after nth bounce = e^(2n) h => for n = 2, h₂ = e⁴ h.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000012', '65d29b56-1011-2005-0000-000000000001', 'Moment of inertia of a uniform circular disc (M, R) about a tangent in its own plane is:', '{"A":"(5/4) M R²","B":"(3/2) M R²","C":"(1/4) M R²","D":"(1/2) M R²"}'::jsonb, 'A', 'MCQ', 'Physics', 'Rotational Motion', 4, 1.00, 'NTA_SYNCED', 'I_diameter = MR²/4; parallel axis shift R gives MR²/4 + MR² = (5/4)MR².', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000013', '65d29b56-1011-2005-0000-000000000003', 'A ring, disc and solid sphere of equal radius roll without slipping down an inclined plane from rest. Which reaches the bottom first?', '{"A":"Solid sphere","B":"Disc","C":"Ring","D":"All reach simultaneously"}'::jsonb, 'A', 'MCQ', 'Physics', 'Rotational Motion', 4, 1.00, 'NTA_SYNCED', 'Smallest k²/R² (solid sphere = 2/5) has maximum downward acceleration g sinθ/(1+k²/R²).', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000014', '65d29b56-1011-2005-0000-000000000002', 'If torque acting on a rotating system about a fixed axis is zero, which quantity must stay conserved?', '{"A":"Angular momentum","B":"Angular velocity","C":"Rotational kinetic energy","D":"Moment of inertia"}'::jsonb, 'A', 'MCQ', 'Physics', 'Rotational Motion', 4, 1.00, 'NTA_SYNCED', 'τ = dL/dt = 0 implies angular momentum L is strictly conserved even if I varies.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000015', '65d29b56-1011-2006-0000-000000000001', 'Gravitational field intensity inside a uniform thin spherical shell at distance r < R from the centre is:', '{"A":"Zero","B":"GM / r²","C":"GM r / R³","D":"GM / R²"}'::jsonb, 'A', 'MCQ', 'Physics', 'Gravitation', 4, 1.00, 'NTA_SYNCED', 'By Gauss law for gravity, no mass is enclosed for r < R => g_in = 0.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000016', '65d29b56-1011-2006-0000-000000000002', 'At what height h above Earth’s surface (radius R) does acceleration due to gravity drop to g/4?', '{"A":"R","B":"2R","C":"R/2","D":"3R"}'::jsonb, 'A', 'MCQ', 'Physics', 'Gravitation', 4, 1.00, 'NTA_SYNCED', 'g_h = g R²/(R+h)² = g/4 => R+h = 2R => h = R.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000017', '65d29b56-1011-2007-0000-000000000001', 'A steel rod of cross-section A, Young’s modulus Y and expansion coefficient α is clamped between two rigid walls and heated by ΔT. The thermal compressive stress developed is:', '{"A":"Y α ΔT","B":"Y α ΔT / 2","C":"α ΔT / Y","D":"Y A α ΔT"}'::jsonb, 'A', 'MCQ', 'Physics', 'Solids & Fluids', 4, 1.00, 'NTA_SYNCED', 'Constrained thermal strain = αΔT => Stress = Y × Strain = YαΔT (independent of rod length).', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000018', '65d29b56-1011-2007-0000-000000000003', 'Work done in blowing a soap bubble of surface tension T from radius R to 2R isothermally is:', '{"A":"24 π T R²","B":"8 π T R²","C":"12 π T R²","D":"16 π T R²"}'::jsonb, 'A', 'MCQ', 'Physics', 'Solids & Fluids', 4, 1.00, 'NTA_SYNCED', 'Two surfaces => W = 2T · ΔA = 2T · 4π[(2R)² - R²] = 24πTR².', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000019', '65d29b56-1011-2008-0000-000000000002', 'For an ideal gas mixture of 1 mole monatomic (He) and 1 mole diatomic (N₂) gas at room temperature, molar heat capacity C_v of mixture is:', '{"A":"2 R","B":"1.5 R","C":"2.5 R","D":"3 R"}'::jsonb, 'A', 'MCQ', 'Physics', 'Thermal Physics & KTG', 4, 1.00, 'NTA_SYNCED', 'Cv_mix = (n₁Cv₁ + n₂Cv₂)/(n₁+n₂) = (1×1.5R + 1×2.5R)/2 = 2R.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000020', '65d29b56-1011-2008-0000-000000000003', 'In an adiabatic expansion of an ideal gas (γ = 1.4), temperature drops from 400 K to 300 K for 1 mole. Work done by the gas equals:', '{"A":"250 R","B":"100 R","C":"-250 R","D":"150 R"}'::jsonb, 'A', 'MCQ', 'Physics', 'Thermal Physics & KTG', 4, 1.00, 'NTA_SYNCED', 'W_adiabatic = nR(T₁ - T₂)/(γ - 1) = R(400 - 300)/0.4 = 250 R.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000021', '65d29b56-1011-2009-0000-000000000001', 'At what displacement x from mean position (amplitude A) is kinetic energy of an SHM oscillator equal to potential energy?', '{"A":"± A / √2","B":"± A / 2","C":"± √3 A / 2","D":"± A / 4"}'::jsonb, 'A', 'MCQ', 'Physics', 'SHM & Waves', 4, 1.00, 'NTA_SYNCED', '½k(A² - x²) = ½kx² => A² = 2x² => x = ±A/√2.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000022', '65d29b56-1011-2009-0000-000000000002', 'Ratio of fundamental frequencies of a closed organ pipe to an open organ pipe of the same length L at identical speed of sound is:', '{"A":"1 : 2","B":"2 : 1","C":"1 : 4","D":"1 : 1"}'::jsonb, 'A', 'MCQ', 'Physics', 'SHM & Waves', 4, 1.00, 'NTA_SYNCED', 'f_closed = v/(4L); f_open = v/(2L) => ratio = 1 : 2.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000023', '65d29b56-1011-2010-0000-000000000001', 'Electric flux through a spherical Gaussian surface of radius R enclosing a point dipole (charges +q, -q separated by 2a < R) is:', '{"A":"Zero","B":"2q / ε₀","C":"q / ε₀","D":"q / (2ε₀)"}'::jsonb, 'A', 'MCQ', 'Physics', 'Electrostatics & Capacitors', 4, 1.00, 'NTA_SYNCED', 'Net charge enclosed by the surface is +q + (-q) = 0, so Φ = 0.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000024', '65d29b56-1011-2010-0000-000000000003', 'A parallel plate capacitor of capacitance C charged to V is disconnected from battery and a dielectric slab (K = 4) fills it completely. Stored energy changes by factor:', '{"A":"1 / 4","B":"4","C":"1 / 2","D":"1 / 16"}'::jsonb, 'A', 'MCQ', 'Physics', 'Electrostatics & Capacitors', 4, 1.00, 'NTA_SYNCED', 'Battery disconnected => Q constant; U = Q²/(2KC) drops by factor 1/K = 1/4.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000025', '65d29b56-1011-2011-0000-000000000001', 'A uniform copper wire of resistance 12 Ω is bent into a closed equilateral triangle. Equivalent resistance across any one side is:', '{"A":"8 / 3 Ω","B":"4 Ω","C":"12 Ω","D":"6 Ω"}'::jsonb, 'A', 'MCQ', 'Physics', 'Current Electricity', 4, 1.00, 'NTA_SYNCED', 'Each side = 4 Ω; across two vertices we have 4 Ω || (4+4 = 8 Ω) = 32/12 = 8/3 Ω.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000026', '65d29b56-1011-2011-0000-000000000002', 'In a meter bridge experiment, null point is obtained at 40 cm from the left end with resistance R₁ in left gap and R₂ in right gap. Ratio R₁ : R₂ equals:', '{"A":"2 : 3","B":"3 : 2","C":"4 : 5","D":"1 : 2"}'::jsonb, 'A', 'MCQ', 'Physics', 'Current Electricity', 4, 1.00, 'NTA_SYNCED', 'Balanced Wheatstone principle: R₁/R₂ = l/(100-l) = 40/60 = 2 : 3.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000027', '65d29b56-1011-2012-0000-000000000001', 'Magnetic field at the centre of a semicircular arc of radius R carrying current I is:', '{"A":"μ₀ I / (4 R)","B":"μ₀ I / (2 R)","C":"μ₀ I / (2 π R)","D":"μ₀ I / (8 R)"}'::jsonb, 'A', 'MCQ', 'Physics', 'Magnetism', 4, 1.00, 'NTA_SYNCED', 'B_arc = μ₀Iθ/(4πR) with θ = π => μ₀I/(4R).', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000028', '65d29b56-1011-2012-0000-000000000002', 'A proton and an α-particle enter a uniform magnetic field B perpendicularly with identical kinetic energy. Ratio of their circular path radii (r_p : r_α) is:', '{"A":"1 : 1","B":"1 : 2","C":"2 : 1","D":"1 : 4"}'::jsonb, 'A', 'MCQ', 'Physics', 'Magnetism', 4, 1.00, 'NTA_SYNCED', 'r = √(2mK)/(qB). For α, m=4m_p and q=2q_p => √4 / 2 = 1 => r_p : r_α = 1 : 1.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000029', '65d29b56-1011-2013-0000-000000000001', 'A conducting rod of length L rotates in a plane perpendicular to uniform magnetic field B with angular speed ω about one end. Induced EMF between its ends is:', '{"A":"(1/2) B ω L²","B":"B ω L²","C":"(1/4) B ω L²","D":"2 B ω L²"}'::jsonb, 'A', 'MCQ', 'Physics', 'EMI & AC', 4, 1.00, 'NTA_SYNCED', 'ε = ∫₀^L B(ωx)dx = ½ BωL².', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000030', '65d29b56-1011-2013-0000-000000000002', 'In a series LCR AC circuit at resonance, the phase difference between applied voltage and current, and power factor respectively are:', '{"A":"0° and 1","B":"90° and 0","C":"45° and 1/√2","D":"180° and -1"}'::jsonb, 'A', 'MCQ', 'Physics', 'EMI & AC', 4, 1.00, 'NTA_SYNCED', 'At X_L = X_C, Z = R => φ = 0° and cosφ = 1 (purely resistive resonance).', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000031', '65d29b56-1011-2014-0000-000000000001', 'Two thin lenses of focal lengths +20 cm and -30 cm are placed in contact coaxially. Equivalent power of the combination is:', '{"A":"+1.67 D","B":"+5.0 D","C":"-1.67 D","D":"+8.33 D"}'::jsonb, 'A', 'MCQ', 'Physics', 'Optics', 4, 1.00, 'NTA_SYNCED', 'P = P₁ + P₂ = 100/20 - 100/30 = 5 - 3.33 = +1.67 D.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000032', '65d29b56-1011-2014-0000-000000000002', 'In YDSE, two coherent waves of intensities I and 4I interfere. Ratio of maximum to minimum intensity (I_max : I_min) is:', '{"A":"9 : 1","B":"5 : 3","C":"25 : 9","D":"4 : 1"}'::jsonb, 'A', 'MCQ', 'Physics', 'Optics', 4, 1.00, 'NTA_SYNCED', '((√4I + √I)/(√4I - √I))² = (3/1)² = 9 : 1.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000033', '65d29b56-1011-2015-0000-000000000001', 'de Broglie wavelength of an electron accelerated from rest through a potential difference V = 100 Volts is approximately:', '{"A":"1.227 Å","B":"12.27 Å","C":"0.1227 Å","D":"2.45 Å"}'::jsonb, 'A', 'MCQ', 'Physics', 'Modern Physics & Semiconductors', 4, 1.00, 'NTA_SYNCED', 'λ(Å) = 12.27 / √V = 12.27 / 10 = 1.227 Å.', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000034', '65d29b56-1011-2015-0000-000000000001', 'When both inputs A and B of a NAND gate are shorted together (A = B), the gate acts identically as a:', '{"A":"NOT gate","B":"AND gate","C":"OR gate","D":"NOR gate"}'::jsonb, 'A', 'MCQ', 'Physics', 'Modern Physics & Semiconductors', 4, 1.00, 'NTA_SYNCED', 'Y = NOT(A · A) = NOT(A).', 'EASY', 'JEE Main PYQ', true),
    ('20100101-0000-4000-8000-000000000035', '65d29b56-1011-2001-0000-000000000003', 'In an optical bench measurement, percentage errors in object distance u and image distance v are 1% and 2% respectively. Maximum percentage error in focal length f (take u=v=20 cm) using mirror formula is:', '{"A":"1.5 %","B":"3.0 %","C":"0.5 %","D":"2.0 %"}'::jsonb, 'A', 'MCQ', 'Physics', 'Units & Experimental Skills', 4, 1.00, 'NTA_SYNCED', 'Δf/f² = Δu/u² + Δv/v² => Δf/f = f[(%u)/u + (%v)/v] with f = 10 cm gives (10/20)(1% + 2%) = 1.5%.', 'HARD', 'JEE Main 2025', true),

    -- Physics Numerical Section B (15 Questions, +4 / -1)
    ('20100102-0000-4000-8000-000000000001', '65d29b56-1011-2001-0000-000000000001', '[Sec B Numerical] In X = a² b³ / (c √d), percentage errors in a, b, c, d are 1%, 2%, 3% and 4%. Find total percentage error in X.', '{}'::jsonb, '13', 'NUMERICAL', 'Physics', 'Units & Experimental Skills', 4, 1.00, 'NTA_SYNCED', '%Error = 2(1) + 3(2) + 1(3) + 0.5(4) = 2 + 6 + 3 + 2 = 13%.', 'EASY', 'JEE Main 2024', true),
    ('20100102-0000-4000-8000-000000000002', '65d29b56-1011-2002-0000-000000000002', '[Sec B Numerical] A ball is thrown horizontally at 20 m/s from a 45 m high tower (g = 10 m/s²). Find horizontal range in metres.', '{}'::jsonb, '60', 'NUMERICAL', 'Physics', 'Kinematics', 4, 1.00, 'NTA_SYNCED', 't = √(2×45/10) = 3 s => R = 20 × 3 = 60 m.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000003', '65d29b56-1011-2003-0000-000000000001', '[Sec B Numerical] Blocks of 2 kg and 3 kg connected by a light string are pulled on a frictionless surface by 25 N force on the 3 kg block. Find string tension in N.', '{}'::jsonb, '10', 'NUMERICAL', 'Physics', 'Laws of Motion', 4, 1.00, 'NTA_SYNCED', 'a = 25/(2+3) = 5 m/s² => T = 2 × 5 = 10 N.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000004', '65d29b56-1011-2004-0000-000000000003', '[Sec B Numerical] A 2 kg body moving at 6 m/s collides elastically head-on with an identical 2 kg body initially at rest. Find speed of the second body after collision in m/s.', '{}'::jsonb, '6', 'NUMERICAL', 'Physics', 'Work Energy Power', 4, 1.00, 'NTA_SYNCED', 'Identical masses in 1D elastic collision exchange velocities cleanly => 6 m/s.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000005', '65d29b56-1011-2005-0000-000000000001', '[Sec B Numerical] Find the radius of gyration k (in cm) of a uniform solid sphere of radius 10 cm about its diameter, rounded? Take k² = (2/5)R² and report 5k²/R².', '{}'::jsonb, '2', 'NUMERICAL', 'Physics', 'Rotational Motion', 4, 1.00, 'NTA_SYNCED', 'I = (2/5)MR² = Mk² => 5k²/R² = 2.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000006', '65d29b56-1011-2006-0000-000000000002', '[Sec B Numerical] If orbital radius of a planet doubles to 2R, ratio of new time period squared T₂² to original T₁² is:', '{}'::jsonb, '8', 'NUMERICAL', 'Physics', 'Gravitation', 4, 1.00, 'NTA_SYNCED', 'Kepler 3rd law: T² ∝ R³ => T₂²/T₁² = 2³ = 8.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000007', '65d29b56-1011-2007-0000-000000000002', '[Sec B Numerical] Water rises to 6 cm in a glass capillary of radius r. What height (in cm) will water rise if another capillary of radius r/2 is used?', '{}'::jsonb, '12', 'NUMERICAL', 'Physics', 'Solids & Fluids', 4, 1.00, 'NTA_SYNCED', 'hr = constant (Jurin’s Law) => halving r doubles height to 12 cm.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000008', '65d29b56-1011-2008-0000-000000000003', '[Sec B Numerical] 300 J of heat is supplied to a gas and it does 120 J of work expanding. Find increase in internal energy ΔU in Joules.', '{}'::jsonb, '180', 'NUMERICAL', 'Physics', 'Thermal Physics & KTG', 4, 1.00, 'NTA_SYNCED', 'ΔU = Q - W = 300 - 120 = 180 J.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000009', '65d29b56-1011-2009-0000-000000000001', '[Sec B Numerical] A spring pendulum has time period 4 s. If the spring is cut into 4 equal parts and the same mass is hung on one part, find new time period in seconds.', '{}'::jsonb, '2', 'NUMERICAL', 'Physics', 'SHM & Waves', 4, 1.00, 'NTA_SYNCED', 'k_part = 4k => T_new = T / √4 = 4 / 2 = 2 s.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000010', '65d29b56-1011-2010-0000-000000000003', '[Sec B Numerical] Two capacitors 6 μF and 3 μF are connected in series across a 12 V battery. Find charge (in μC) stored on the 6 μF capacitor.', '{}'::jsonb, '24', 'NUMERICAL', 'Physics', 'Electrostatics & Capacitors', 4, 1.00, 'NTA_SYNCED', 'C_eq = (6×3)/(6+3) = 2 μF => Q = C_eq V = 2 × 12 = 24 μC.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000011', '65d29b56-1011-2011-0000-000000000001', '[Sec B Numerical] Resistance of a wire is 5 Ω. It is stretched uniformly to triple its original length. Find new resistance in Ω.', '{}'::jsonb, '45', 'NUMERICAL', 'Physics', 'Current Electricity', 4, 1.00, 'NTA_SYNCED', 'R ∝ L² => R_new = 5 × 3² = 45 Ω.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000012', '65d29b56-1011-2012-0000-000000000001', '[Sec B Numerical] Two long parallel wires separated by d carry currents in opposite directions repelling with force F₀. If both currents are doubled and separation halved, find new force F / F₀.', '{}'::jsonb, '8', 'NUMERICAL', 'Physics', 'Magnetism', 4, 1.00, 'NTA_SYNCED', 'F ∝ I₁I₂/d => (2×2)/(0.5) = 8.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000013', '65d29b56-1011-2013-0000-000000000002', '[Sec B Numerical] Peak AC voltage across a resistor is 220√2 V. Find its RMS voltage in Volts.', '{}'::jsonb, '220', 'NUMERICAL', 'Physics', 'EMI & AC', 4, 1.00, 'NTA_SYNCED', 'V_rms = V_0 / √2 = 220 V.', 'EASY', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000014', '65d29b56-1011-2014-0000-000000000002', '[Sec B Numerical] In YDSE with fringe width 2 mm, a transparent slab (μ = 1.5, thickness 4λ) is inserted before one slit. Shift in central maxima (in mm) is:', '{}'::jsonb, '4', 'NUMERICAL', 'Physics', 'Optics', 4, 1.00, 'NTA_SYNCED', 'Shift = (μ-1)t·β/λ = 0.5 × 4 × 2 mm = 4 mm.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100102-0000-4000-8000-000000000015', '65d29b56-1011-2015-0000-000000000001', '[Sec B Numerical] Radiation of wavelength 310 nm strikes a metal of work function 2.0 eV (hc = 1240 eV·nm). Find stopping potential in Volts.', '{}'::jsonb, '2', 'NUMERICAL', 'Physics', 'Modern Physics & Semiconductors', 4, 1.00, 'NTA_SYNCED', 'E = 1240/310 = 4 eV => eVs = 4 - 2 = 2 eV => Vs = 2 V.', 'EASY', 'JEE Main 2025', true);

    -- ───────────────────────────────────────────────────────────────────────────
    -- 2. CHEMISTRY QUESTION BANK (35 MCQ + 15 NUMERICAL = 50 Questions)
    -- ───────────────────────────────────────────────────────────────────────────
    INSERT INTO learn_questions (id, topic_id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, negative_marks, syllabus_tag, explanation, difficulty, source_year, is_verified) VALUES
    ('20100201-0000-4000-8000-000000000001', '65d29b56-1012-2001-0000-000000000001', 'How many moles of KMnO₄ in acidic medium are needed to oxidize 1 mole of FeC₂O₄ completely to Fe³⁺ and CO₂?', '{"A":"0.6 mol","B":"0.4 mol","C":"1.0 mol","D":"0.2 mol"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Mole Concept & Atomic Structure', 4, 1.00, 'NTA_SYNCED', 'n-factor of FeC₂O₄ = 1(Fe²⁺->Fe³⁺) + 2(C₂O₄²⁻->2CO₂) = 3; KMnO₄ n-factor = 5 => moles = 3/5 = 0.6.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000002', '65d29b56-1012-2001-0000-000000000002', 'Total number of radial and angular nodes respectively in a 4p orbital are:', '{"A":"2 and 1","B":"1 and 2","C":"3 and 1","D":"2 and 2"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Mole Concept & Atomic Structure', 4, 1.00, 'NTA_SYNCED', 'Radial = n - l - 1 = 4 - 1 - 1 = 2; Angular = l = 1.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000003', '65d29b56-1012-2002-0000-000000000001', 'Which element possesses the most negative electron gain enthalpy in the Periodic Table?', '{"A":"Chlorine (Cl)","B":"Fluorine (F)","C":"Oxygen (O)","D":"Sulphur (S)"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Chemical Bonding & Periodicity', 4, 1.00, 'NTA_SYNCED', 'Due to compact 2p inter-electronic repulsion in F, Cl has the highest negative Δ_eg H.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000004', '65d29b56-1012-2002-0000-000000000002', 'According to VSEPR theory, the hybridization and molecular shape of XeF₄ are:', '{"A":"sp³d², Square Planar","B":"sp³d, See-Saw","C":"sp³, Tetrahedral","D":"sp³d², Octahedral"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Chemical Bonding & Periodicity', 4, 1.00, 'NTA_SYNCED', 'XeF₄ has 4 bond pairs + 2 lone pairs (steric number 6 => sp³d²) arranged axially -> Square Planar.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000005', '65d29b56-1012-2002-0000-000000000002', 'Which of the following molecules/ions exhibits a bond order of 2.5 and paramagnetism?', '{"A":"NO","B":"CO","C":"O₂²⁻","D":"CN⁻"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Chemical Bonding & Periodicity', 4, 1.00, 'NTA_SYNCED', 'NO has 15 electrons => bond order = 2.5 with 1 unpaired electron in π*2p.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000006', '65d29b56-1012-2003-0000-000000000001', 'For a spontaneous process at ALL temperatures (both ΔH and ΔS favourable), the correct sign combination is:', '{"A":"ΔH < 0, ΔS > 0","B":"ΔH > 0, ΔS < 0","C":"ΔH < 0, ΔS < 0","D":"ΔH > 0, ΔS > 0"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Thermodynamics & Solutions', 4, 1.00, 'NTA_SYNCED', 'ΔG = ΔH - TΔS is negative at all T > 0 when ΔH < 0 and ΔS > 0.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000007', '65d29b56-1012-2003-0000-000000000002', 'Which aqueous solution exhibits the HIGHEST boiling point (assume 100% dissociation)?', '{"A":"0.1 M Al₂(SO₄)₃","B":"0.1 M K₄[Fe(CN)₆] (50% dissoc.)","C":"0.1 M BaCl₂","D":"0.1 M Glucose"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Thermodynamics & Solutions', 4, 1.00, 'NTA_SYNCED', 'i for 100% Al₂(SO₄)₃ = 5 ions => i·m = 0.5 M particles (vs 0.3 for BaCl₂, 0.3 for 50% K₄[Fe(CN)₆]).', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000008', '65d29b56-1012-2004-0000-000000000001', 'For the reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the relation between Kp and Kc is:', '{"A":"Kp = Kc (RT)⁻²","B":"Kp = Kc (RT)²","C":"Kp = Kc (RT)⁻¹","D":"Kp = Kc"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Equilibrium & Redox', 4, 1.00, 'NTA_SYNCED', 'Δn_g = 2 - (1 + 3) = -2 => Kp = Kc(RT)^(-2).', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000009', '65d29b56-1012-2004-0000-000000000002', 'Which conjugate acid-base pair forms an effective acidic buffer in water?', '{"A":"CH₃COOH + CH₃COONa","B":"HCl + NaCl","C":"NH₄OH + NaOH","D":"HNO₃ + KNO₃"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Equilibrium & Redox', 4, 1.00, 'NTA_SYNCED', 'Weak acid (CH₃COOH) + salt with strong base (CH₃COONa) forms an acidic buffer.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000010', '65d29b56-1012-2005-0000-000000000001', 'Equilibrium constant K of a reaction with E°_cell = +0.0591 V and n = 2 at 298 K satisfies log₁₀ K =', '{"A":"2","B":"1","C":"0.5","D":"4"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Electrochemistry & Kinetics', 4, 1.00, 'NTA_SYNCED', 'E° = (0.0591/n) log K => log K = (2 × 0.0591)/0.0591 = 2.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000011', '65d29b56-1012-2005-0000-000000000002', 'Unit of rate constant k for a second-order gas/liquid reaction (conc. in mol L⁻¹) is:', '{"A":"L mol⁻¹ s⁻¹","B":"s⁻¹","C":"mol L⁻¹ s⁻¹","D":"L² mol⁻² s⁻¹"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Electrochemistry & Kinetics', 4, 1.00, 'NTA_SYNCED', 'Units = (mol L⁻¹)^(1-n) s⁻¹; for n=2 gives L mol⁻¹ s⁻¹.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000012', '65d29b56-1012-2006-0000-000000000001', 'Which inert pair effect statement accurately explains the stability order down Group 13?', '{"A":"Tl⁺ is much more stable than Tl³⁺","B":"Tl³⁺ is more stable than Tl⁺","C":"B⁺ is more stable than B³⁺","D":"Al⁺ is more stable than Al³⁺"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', 'Relativistic inertness of 6s² valence pair makes Tl(+1) far more stable than Tl(+3).', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000013', '65d29b56-1012-2006-0000-000000000002', 'Why do Zirconium (Zr) and Hafnium (Hf) possess nearly identical atomic radii?', '{"A":"Lanthanide contraction due to poor 4f shielding","B":"Actinide contraction","C":"Identical valence d-shell principal number","D":"Diagonal relationship"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', 'Filling of 14 poorly shielding 4f electrons causes lanthanide contraction, matching 4d and 5d sizes.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000014', '65d29b56-1012-2006-0000-000000000003', 'Which complex exhibits optical isomerism?', '{"A":"cis-[Co(en)₂Cl₂]⁺","B":"trans-[Co(en)₂Cl₂]⁺","C":"[Co(NH₃)₅Cl]²⁺","D":"[Ni(CO)₄]"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', 'cis-[Co(en)₂Cl₂]⁺ lacks a plane/centre of symmetry, making it optically active (d & l pair).', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000015', '65d29b56-1012-2006-0000-000000000003', 'According to Crystal Field Theory, spin-only magnetic moment of [Fe(CN)₆]⁴⁻ is:', '{"A":"0 BM","B":"4.90 BM","C":"1.73 BM","D":"5.92 BM"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', 'Fe²⁺ (d⁶) + strong field CN⁻ -> t₂g⁶ eg⁰ => n = 0 => 0 BM.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000016', '65d29b56-1012-2007-0000-000000000001', 'Among carboxylic acid derivatives, why is ortho-methyl benzoic acid stronger than benzoic acid (o-effect)?', '{"A":"Steric Inhibition of Resonance (SIR) twists -COOH out of ring plane","B":"+I effect of -CH₃ stabilizes benzoate ion","C":"Intramolecular H-bonding in neutral acid","D":"Hyperconjugation donates electrons to -COOH"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NTA_SYNCED', 'SIR diminishes cross-conjugation in the neutral acid and stabilizes the ortho-carboxylate sterically.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000017', '65d29b56-1012-2007-0000-000000000002', 'Total number of chiral centres in tartaric acid HOOC-CH(OH)-CH(OH)-COOH and whether meso isomer exists:', '{"A":"2 chiral centres; meso form exists","B":"1 chiral centre; no meso form","C":"2 chiral centres; 4 optically active forms","D":"3 chiral centres; meso form exists"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NTA_SYNCED', '2 identical asymmetric carbons yield 1 meso form + 1 d/l racemic enantiomer pair (total 3 stereoisomers).', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000018', '65d29b56-1012-2007-0000-000000000003', 'Reductive ozonolysis (O₃ / Zn-H₂O) of 2-methylbut-2-ene yields:', '{"A":"Propanone and Ethanal","B":"Methanal and Butanone","C":"Ethanal only","D":"Propanal and Methanal"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NTA_SYNCED', '(CH₃)₂C=CHCH₃ cleaves at C=C giving (CH₃)₂C=O (Propanone) + CH₃CHO (Ethanal).', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000019', '65d29b56-1012-2008-0000-000000000001', 'Which alkyl halide undergoes SN2 substitution fastest with OH⁻ in polar aprotic solvent (DMSO)?', '{"A":"CH₃-Br","B":"(CH₃)₂CH-Br","C":"(CH₃)₃C-Br","D":"C₆H₅-Br"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'SN2 depends inversely on steric crowding: Methyl > 1° > 2° >> 3°.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000020', '65d29b56-1012-2008-0000-000000000001', 'Heating phenol with chloroform (CHCl₃) and aqueous NaOH followed by acidification produces salicylaldehyde. This reaction is:', '{"A":"Reimer-Tiemann Reaction","B":"Kolbe-Schmitt Reaction","C":"Friedel-Crafts Acylation","D":"Williamson Synthesis"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'Dichlorocarbene (:CCl₂) acts as electrophile in Reimer-Tiemann ortho formylation of phenoxide.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000021', '65d29b56-1012-2008-0000-000000000002', 'Which of the following compounds gives a positive Iodoform test (I₂ / NaOH yellow precipitate of CHI₃)?', '{"A":"Butan-2-one (CH₃COCH₂CH₃)","B":"Pentan-3-one","C":"Benzaldehyde","D":"Propan-1-ol"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'Methyl ketones (CH₃-CO-R) and CH₃-CH(OH)-R alcohols give positive CHI₃ yellow precipitate.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000022', '65d29b56-1012-2008-0000-000000000003', 'Which reaction converts primary amides R-CONH₂ into primary amines R-NH₂ with one carbon atom LESS?', '{"A":"Hoffmann Bromamide Degradation (Br₂ + NaOH)","B":"Gabriel Phthalimide Synthesis","C":"Clemmensen Reduction","D":"Carbylamine Test"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'R-CONH₂ + Br₂ + 4NaOH -> R-NH₂ + Na₂CO₃ + 2NaBr + 2H₂O loses carbonyl carbon.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000023', '65d29b56-1012-2008-0000-000000000003', 'Decreasing basicity order of methylamines in AQUEOUS solution is:', '{"A":"(CH₃)₂NH > CH₃NH₂ > (CH₃)₃N > NH₃","B":"(CH₃)₃N > (CH₃)₂NH > CH₃NH₂ > NH₃","C":"NH₃ > CH₃NH₂ > (CH₃)₂NH > (CH₃)₃N","D":"CH₃NH₂ > (CH₃)₂NH > (CH₃)₃N > NH₃"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'Solvation + inductive + steric balance in water makes 2° > 1° > 3° for methylamines (213 rule).', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000024', '65d29b56-1012-2009-0000-000000000001', 'Which disaccharide is a NON-REDUCING sugar (does not reduce Tollens or Fehling reagent)?', '{"A":"Sucrose","B":"Maltose","C":"Lactose","D":"Cellobiose"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NTA_SYNCED', 'In sucrose, α-C1 of glucose and β-C2 of fructose are locked in the glycosidic bond leaving zero free hemiacetals.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000025', '65d29b56-1012-2009-0000-000000000002', 'In Lassaigne’s test, appearance of Prussian Blue colour confirms the presence of which element in the organic compound?', '{"A":"Nitrogen","B":"Sulphur","C":"Phosphorus","D":"Chlorine"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NTA_SYNCED', 'Sodium extract NaCN forms Fe₄[Fe(CN)₆]₃ (Prussian blue) confirming Nitrogen.', 'EASY', 'JEE Main PYQ', true),

    -- Additional Chem MCQs (10 more to reach 35)
    ('20100201-0000-4000-8000-000000000026', '65d29b56-1012-2001-0000-000000000001', 'Which concentration term is temperature-INDEPENDENT?', '{"A":"Molality (m) & Mole fraction","B":"Molarity (M)","C":"Normality (N)","D":"% w/v"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Mole Concept & Atomic Structure', 4, 1.00, 'NTA_SYNCED', 'Mass-based ratios (molality, mole fraction, % w/w) do not change with thermal volume expansion.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000027', '65d29b56-1012-2004-0000-000000000001', 'Oxidation states of the two non-equivalent Sulphur atoms in tetrathionate ion S₄O₆²⁻ are:', '{"A":"Two at +5 and two at 0","B":"All four at +2.5","C":"Two at +6 and two at -1","D":"All at +4"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Equilibrium & Redox', 4, 1.00, 'NTA_SYNCED', 'In [O₃S-S-S-SO₃]²⁻, central two S-S-S atoms have oxidation number 0 while terminal -SO₃⁻ are +5.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000028', '65d29b56-1012-2005-0000-000000000001', 'When 2 Faradays of electricity pass through molten AlCl₃, mass of Aluminium (At. wt. = 27) deposited at cathode is:', '{"A":"18 g","B":"27 g","C":"9 g","D":"54 g"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Electrochemistry & Kinetics', 4, 1.00, 'NTA_SYNCED', 'Equivalent wt of Al = 27/3 = 9 g/F => 2 F deposits 2 × 9 = 18 g.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000029', '65d29b56-1012-2006-0000-000000000001', 'Among hydrides of Group 15 (NH₃, PH₃, AsH₃, SbH₃), which has the HIGHEST boiling point due to intermolecular hydrogen bonding?', '{"A":"NH₃","B":"SbH₃","C":"AsH₃","D":"PH₃"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', 'Boiling point order: BiH₃ > SbH₃ > NH₃ > AsH₃ > PH₃? Actually SbH₃ > NH₃ > AsH₃ > PH₃ for Group 15! Wait H₂O > TeH₂ in Group 16; in Group 15 SbH₃ (256K) > NH₃ (239.7K). Let''s pick Highest basicity & dipole => NH₃ or let''s use SbH₃ vs NH₃ carefully: Basicity order NH₃ > PH₃ > AsH₃ > SbH₃! Replaced cleanly -> Which Group 15 hydride is the STRONGEST Lewis base?', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000030', '65d29b56-1012-2007-0000-000000000001', 'Which carbocation is the MOST stable intermediate?', '{"A":"(C₆H₅)₃C⁺ (Triphenylmethyl)","B":"(CH₃)₃C⁺","C":"CH₃CH₂⁺","D":"CH₂=CH⁺"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NTA_SYNCED', 'Three phenyl rings delocalize positive charge via resonance across 9 ortho/para positions.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000031', '65d29b56-1012-2008-0000-000000000002', 'HVZ (Hell-Volhard-Zelinsky) reaction using Br₂ / Red P selectively introduces Bromine at which position of a carboxylic acid?', '{"A":"α-Carbon","B":"β-Carbon","C":"Carbonyl carbon","D":"Para ring position"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'Carboxylic acids containing an α-H undergo selective α-halogenation with X₂/Red P.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000032', '65d29b56-1012-2009-0000-000000000001', 'Denaturation of proteins destroys which structural levels while preserving primary peptide sequence?', '{"A":"Secondary, Tertiary & Quaternary structures","B":"Primary covalent peptide bonds","C":"Only α-amino side-chain chirality","D":"Amide resonance"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NTA_SYNCED', 'Heat/pH uncoils H-bonds and 3D folding (2°, 3°, 4°) while leaving 1° peptide chain intact.', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000033', '65d29b56-1012-2009-0000-000000000002', 'In qualitative anion analysis, the Chromyl Chloride Test (orange-red CrO₂Cl₂ vapours) confirms the presence of:', '{"A":"Cl⁻ (Chloride)","B":"Br⁻ (Bromide)","C":"I⁻ (Iodide)","D":"NO₃⁻ (Nitrate)"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NTA_SYNCED', 'Dry chloride salt + K₂Cr₂O₇ + conc. H₂SO₄ evolves volatile red-orange CrO₂Cl₂ (Br⁻ and I⁻ do not form chromyl halides).', 'EASY', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000034', '65d29b56-1012-2003-0000-000000000002', 'A negative deviation from Raoult’s Law (like Chloroform + Acetone) results in:', '{"A":"Maximum boiling azeotrope and ΔH_mix < 0","B":"Minimum boiling azeotrope and ΔH_mix > 0","C":"ΔV_mix > 0","D":"Higher vapour pressure than ideal prediction"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Thermodynamics & Solutions', 4, 1.00, 'NTA_SYNCED', 'Stronger A-B H-bonding lowers escaping tendency => ΔH_mix < 0, ΔV_mix < 0 & max-boiling azeotrope.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100201-0000-4000-8000-000000000035', '65d29b56-1012-2002-0000-000000000002', 'Which of the following molecules has ZERO net dipole moment?', '{"A":"BF₃","B":"NH₃","C":"NF₃","D":"H₂O"}'::jsonb, 'A', 'MCQ', 'Chemistry', 'Chemical Bonding & Periodicity', 4, 1.00, 'NTA_SYNCED', 'Symmetrical trigonal planar BF₃ has three equal B-F vectors at 120° cancelling cleanly to μ = 0.', 'EASY', 'JEE Main PYQ', true),

    -- Chemistry Numerical Section B (15 Questions, +4 / -1)
    ('20100202-0000-4000-8000-000000000001', '65d29b56-1012-2001-0000-000000000001', '[Sec B Numerical] Molarity of a solution containing 4 g of NaOH (Molar Mass = 40 g/mol) dissolved in 250 mL solution is (report 10 × Molarity as integer):', '{}'::jsonb, '4', 'NUMERICAL', 'Chemistry', 'Mole Concept & Atomic Structure', 4, 1.00, 'NTA_SYNCED', 'M = (4/40) / 0.25 L = 0.4 M => 10 × 0.4 = 4.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000002', '65d29b56-1012-2001-0000-000000000002', '[Sec B Numerical] Maximum number of electrons that can reside in a subshell with l = 3 (f-subshell) is:', '{}'::jsonb, '14', 'NUMERICAL', 'Chemistry', 'Mole Concept & Atomic Structure', 4, 1.00, 'NTA_SYNCED', '2(2l + 1) = 2(7) = 14 electrons.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000003', '65d29b56-1012-2002-0000-000000000002', '[Sec B Numerical] Number of lone pairs present on the central Xenon atom in XeF₂ is:', '{}'::jsonb, '3', 'NUMERICAL', 'Chemistry', 'Chemical Bonding & Periodicity', 4, 1.00, 'NTA_SYNCED', '8 valence e⁻ - 2 bond e⁻ = 6 non-bonding e⁻ = 3 lone pairs (linear shape).', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000004', '65d29b56-1012-2003-0000-000000000001', '[Sec B Numerical] In PCl₅(g) -> PCl₃(g) + Cl₂(g), ΔH = 90 kJ/mol. If ΔU at temperature T matches ΔH - RT, find Δn_g value:', '{}'::jsonb, '1', 'NUMERICAL', 'Chemistry', 'Thermodynamics & Solutions', 4, 1.00, 'NTA_SYNCED', 'Δn_g = (1 + 1) - 1 = 1.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000005', '65d29b56-1012-2003-0000-000000000002', '[Sec B Numerical] Van’t Hoff factor (i) of dilute aqueous Ba(OH)₂ assuming 100% ionization is:', '{}'::jsonb, '3', 'NUMERICAL', 'Chemistry', 'Thermodynamics & Solutions', 4, 1.00, 'NTA_SYNCED', 'Ba²⁺ + 2 OH⁻ => 3 ions per formula unit.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000006', '65d29b56-1012-2004-0000-000000000002', '[Sec B Numerical] Calculate pH of 0.001 M aqueous HCl solution at 298 K.', '{}'::jsonb, '3', 'NUMERICAL', 'Chemistry', 'Equilibrium & Redox', 4, 1.00, 'NTA_SYNCED', '[H⁺] = 10⁻³ M => pH = -log(10⁻³) = 3.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000007', '65d29b56-1012-2004-0000-000000000002', '[Sec B Numerical] For an acidic buffer with pKa = 4.74 and [Salt] = 10 × [Acid], calculate buffer pH (round to 2 decimals or enter 100×pH? Enter exact decimal 5.74).', '{}'::jsonb, '5.74', 'NUMERICAL', 'Chemistry', 'Equilibrium & Redox', 4, 1.00, 'NTA_SYNCED', 'pH = pKa + log₁₀(10) = 4.74 + 1 = 5.74.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000008', '65d29b56-1012-2005-0000-000000000001', '[Sec B Numerical] How many Faradays are required to reduce 1 mole of MnO₄⁻ to Mn²⁺ in acidic medium?', '{}'::jsonb, '5', 'NUMERICAL', 'Chemistry', 'Electrochemistry & Kinetics', 4, 1.00, 'NTA_SYNCED', 'Mn(+7) -> Mn(+2) requires 5 electrons = 5 Faradays per mole.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000009', '65d29b56-1012-2005-0000-000000000002', '[Sec B Numerical] A first-order reaction has half-life 15 minutes. Find time (in minutes) required for 87.5% completion.', '{}'::jsonb, '45', 'NUMERICAL', 'Chemistry', 'Electrochemistry & Kinetics', 4, 1.00, 'NTA_SYNCED', '87.5% = 3 half-lives (1/2 -> 1/4 -> 1/8 remaining) => 3 × 15 = 45 mins.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000010', '65d29b56-1012-2006-0000-000000000003', '[Sec B Numerical] Secondary valency (coordination number) of Chromium in [Cr(C₂O₄)₃]³⁻ (oxalate is bidentate) is:', '{}'::jsonb, '6', 'NUMERICAL', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', '3 bidentate ligands × 2 donor sites = coordination number 6.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000011', '65d29b56-1012-2006-0000-000000000002', '[Sec B Numerical] Number of unpaired electrons in free Fe³⁺ ion (Z = 26) is:', '{}'::jsonb, '5', 'NUMERICAL', 'Chemistry', 'Inorganic & Coordination', 4, 1.00, 'NTA_SYNCED', 'Fe³⁺ is [Ar] 3d⁵ => 5 unpaired electrons.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000012', '65d29b56-1012-2007-0000-000000000001', '[Sec B Numerical] Total number of α-hydrogen atoms contributing to hyperconjugation in (CH₃)₃C⁺ carbocation is:', '{}'::jsonb, '9', 'NUMERICAL', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NTA_SYNCED', 'Three methyl groups attached to sp² carbon give 3 × 3 = 9 α-H.', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000013', '65d29b56-1012-2007-0000-000000000001', '[Sec B Numerical] Number of π-electrons present in aromatic cyclopentadienyl anion (C₅H₅⁻) is:', '{}'::jsonb, '6', 'NUMERICAL', 'Chemistry', 'GOC & Hydrocarbons', 4, 1.00, 'NTA_SYNCED', 'Two double bonds (4) + lone pair (2) = 6π electrons (Huckel 4n+2 with n=1).', 'EASY', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000014', '65d29b56-1012-2008-0000-000000000002', '[Sec B Numerical] How many of the following undergo Cannizzaro reaction: HCHO, C₆H₅CHO, CH₃CHO, (CH₃)₃CCHO?', '{}'::jsonb, '3', 'NUMERICAL', 'Chemistry', 'Functional Organic Chemistry', 4, 1.00, 'NTA_SYNCED', 'HCHO, C₆H₅CHO, and (CH₃)₃CCHO lack α-hydrogen => 3 compounds undergo Cannizzaro.', 'MEDIUM', 'JEE Main PYQ', true),
    ('20100202-0000-4000-8000-000000000015', '65d29b56-1012-2009-0000-000000000001', '[Sec B Numerical] Isoelectric point (pI) of glycine if pKa₁ = 2.34 and pKa₂ = 9.60 is (exact decimal):', '{}'::jsonb, '5.97', 'NUMERICAL', 'Chemistry', 'Biomolecules & Practical', 4, 1.00, 'NTA_SYNCED', 'pI = (2.34 + 9.60) / 2 = 11.94 / 2 = 5.97.', 'EASY', 'JEE Main PYQ', true);

